// complex ops from https://www.shadertoy.com/view/llySRh
#define cmul(A,B) ( mat2( A, -(A).y, (A).x ) * (B) )  // by deMoivre formula
#define cinv(Z)   ( vec2( (Z).x, -(Z).y ) / dot(Z,Z) ) 
#define cdiv(A,B)   cmul( A, cinv(B) )

// constants
#define PI 3.141593
#define EPSILON 1e-6
#define CYCLES 1000

#define TSCALE (iTime*0.5)
#define dot2(a) dot(a,a)



// used the pattern from Diffusion Shamrock
// https://www.shadertoy.com/view/DdjfDm
vec2 pattern_loc(float theta)
{
    vec2 p = vec2(abs(sin(theta)),sin(theta*2.)/2.) * 0.4;
    float vel = length(vec2(cos(theta)*2.,cos(theta*2.)*2.));

    int cycle = int(theta/PI)%4;

    if(cycle == 1){
        return vec2(-p.y,p.x);
    }else if(cycle == 2){
        return -p;
    }else if(cycle == 3){
        return vec2(p.y,-p.x);
    }
	return p;

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    //scale and rotate to get us where we need to be looking.
    vec2 uv = mat2(cos(TSCALE*-0.5),-sin(TSCALE*-0.5), sin(TSCALE*-0.5),cos(TSCALE*-0.5)) * (
        (fragCoord-iResolution.xy*0.5) / min(iResolution.x,iResolution.y)*0.27 
        + vec2(sin(TSCALE*2.-0.785398),cos(TSCALE*2.-0.785398))*0.21
    );

    //define the three zeroes of a Newton fractal
    vec2 a = pattern_loc(TSCALE+0.0000000);
    vec2 b = pattern_loc(TSCALE+4.1887902);
    vec2 c = pattern_loc(TSCALE+8.3775804);


    //Now compute said fractal
    vec2 f,z = uv;
    float s = 1.;
    for(int i=0;i<CYCLES;i++){
        f = cdiv(
            cmul(cmul(z-a,z-b),z-c),
            3.*cmul(z,z) - 2.*cmul(a+b+c,z) + cmul(a,b) + cmul(a,c) + cmul(b,c)
        );
        s += exp( length(z) - 0.5/length(f) ); //should clamp this, but meh.
        z -= f;
        if(length(f) < EPSILON){
            break;
        }
    }

    //smoothed iteration count, scaled (mostly) from 0..1
    //it _would_ be 0..1 if I had clamped things, but this looks better anyway.
    float br = sqrt(log(s+1.) / log(float(CYCLES+1)));

    //probably overcomplicated, but it works.
    float za = dot2(z-a);
    float zb = dot2(z-b);
    float zc = dot2(z-c);
    float minz = min(min(za,zb),zc);
    float maxz = max(max(za,zb),zc);
    vec3 col = clamp( (cos(br*PI*4.)*0.4+0.6) - (vec3(za,zb,zc) - minz)/(maxz-minz),0.,1.);
    fragColor = vec4(col,clamp(br,0.,1.));
}
